\centering
\begin{tikzpicture}[
  box/.style={rectangle, rounded corners, draw=blue!60, fill=blue!10,
              text centered, minimum height=1cm, minimum width=3.5cm},
  arr/.style={-Stealth, thick}
]
  \node[box] (zig)    at (0, 0)   {\Zig{} Runtime};
  \node[box] (fut)    at (5, 0)   {\Futhark{} Kernels};
